PRAGMA foreign_keys=ON; CREATE TABLE people(id INTEGER PRIMARY KEY,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('requester','agent'))); CREATE TABLE tickets(id INTEGER PRIMARY KEY,subject TEXT NOT NULL,requester_id INTEGER NOT NULL REFERENCES people(id),agent_id INTEGER REFERENCES people(id),priority TEXT NOT NULL CHECK(priority IN('High','Medium','Low')),status TEXT NOT NULL DEFAULT 'Open' CHECK(status IN('Open','Closed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,closed_at TEXT);
